    private array $areaMap = [
        'VTA' => 'Equipo de Ventas',
        'PRO' => 'Producción',
        'ADM' => 'Administración',
        'CC' => 'Control de Calidad',
        'VAL' => 'Validaciones',
        'AC' => 'Aseguramiento de la Calidad',
    ];

    public function run(): void
    {
        $this->crearAreasNuevas();
        $this->crearUsuariosDesdePlantilla();
        $this->resolverJerarquia();
        Area::invalidateHierarchyCache();
    }

    protected function crearAreasNuevas(): void
    {
        $padreAdministrativa = Area::where('nombre', 'Administrativa')->first();
        $padreProduccion = Area::where('nombre', 'Producción')->first();

        $this->createAreaIfMissing('Control de Calidad', 'administrativa', $padreAdministrativa?->id, 6);
        $this->createAreaIfMissing('Validaciones', 'administrativa', $padreAdministrativa?->id, 7);
        $this->createAreaIfMissing('Aseguramiento de la Calidad', 'produccion', $padreProduccion?->id, 3);
        $this->createAreaIfMissing('Administración', 'administrativa', $padreAdministrativa?->id, 6);
    }

    protected function createAreaIfMissing(string $nombre, string $tipo, ?int $parentId, int $orden): Area
    {
        return Area::updateOrCreate(
            ['nombre' => $nombre],
            [
                'codigo' => strtoupper(Str::limit(Str::slug($nombre, '_'), 15, '')),
                'parent_id' => $parentId,
                'tipo' => $tipo,
                'orden' => $orden,
                'activo' => true,
            ],
        );
    }

    protected function crearUsuariosDesdePlantilla(): void
    {
        $rows = $this->parsePlantilla();
        $roles = $this->getRoles();

        foreach ($rows as $row) {
            $codigo = trim($row['codigo_empleado']);
            $carnet = $this->normalizeCarnet(trim($row['carnet_de_identidad']));
            $nombres = trim($row['apellidos_y_nombres']);
            $centro = trim($row['centro_de_costos']);
            $fecha_nac = $this->parseDate(trim($row['fecha_nacimiento']));
            $sexo = trim($row['sexo']);
            $ocupacion = trim($row['ocupacion']);
            $fecha_ingreso = $this->parseDate(trim($row['fecha_ingreso']));

            $areaNombre = $this->areaMap[$centro] ?? null;
            if (! $areaNombre) {
                continue;
            }
            $area = Area::where('nombre', $areaNombre)->first();
            if (! $area) {
                continue;
            }

            $email = $this->generateEmail($carnet, $codigo);

            $parts = $this->parseNombres($nombres);

            $user = User::where('codigo_empleado', $codigo)->orWhere('carnet', $carnet)->first();
            if ($user) {
                $user->update([
                    'name' => $parts['name'],
                    'email' => $email,
                    'nombre1' => $parts['nombre1'],
                    'nombre2' => $parts['nombre2'],
                    'apellido1' => $parts['apellido1'],
                    'apellido2' => $parts['apellido2'],
                    'genero' => $sexo,
                    'fecha_nacimiento' => $fecha_nac,
                    'fecha_contrato' => $fecha_ingreso,
                    'area_id' => $area->id,
                    'codigo_empleado' => $codigo,
                    'carnet' => $carnet,
                    'ocupacion_original' => $ocupacion,
                    'password' => Hash::make('password'),
                    'email_verified_at' => now(),
                ]);
            } else {
                $user = User::create([
                    'name' => $parts['name'],
                    'email' => $email,
                    'nombre1' => $parts['nombre1'],
                    'nombre2' => $parts['nombre2'],
                    'apellido1' => $parts['apellido1'],
                    'apellido2' => $parts['apellido2'],
                    'genero' => $sexo,
                    'fecha_nacimiento' => $fecha_nac,
                    'fecha_contrato' => $fecha_ingreso,
                    'area_id' => $area->id,
                    'codigo_empleado' => $codigo,
                    'carnet' => $carnet,
                    'ocupacion_original' => $ocupacion,
                    'password' => Hash::make('password'),
                    'email_verified_at' => now(),
                ]);
            }

            [$rol, $esJefe] = $this->getRoleByOccupation($ocupacion);
            if (! isset($roles[$rol])) {
                $rol = 'trabajador';
            }
            $user->assignRole($roles[$rol]);

            if ($esJefe) {
                $user->areas()->syncWithoutDetaching([$area->id => ['es_jefe' => true]]);
            }
        }
    }

    protected function resolverJerarquia(): void
    {
        $users = User::whereNotNull('codigo_empleado')->get()->keyBy('codigo_empleado');
        $areaHeadMap = [];

        foreach ($users as $codigo => $user) {
            $areaHeadMap[$user->area_id] = $user->id;
        }

        foreach ($users as $codigo => $user) {
            $superiorId = $this->findSuperior($user, $users);
            if ($superiorId && $superiorId !== $user->id) {
                $user->update(['superior_id' => $superiorId]);
            }
        }

        foreach ($users as $codigo => $user) {
            if ($user->hasRole('supervisor') || $user->hasRole('admin')) {
                $area = $user->area;
                if ($area && ! $area->head_user_id) {
                    $area->update(['head_user_id' => $user->id]);
                }
            }
        }
    }

    protected function findSuperior(User $user, Collection $users): ?int
    {
        $ocupacion = strtoupper($user->ocupacion_original ?? '');
        $areaId = $user->area_id;

        if (str_contains($ocupacion, 'GERENTE GENERAL')) {
            return null;
        }

        if (preg_match('/GERENTE (ADMINISTRATIVO|COMERCIAL|DE MARKETING|OPERACIONES|REGIONAL)/', $ocupacion)) {
            return $this->findByRoleAndArea('admin', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'DIRECTOR TECNICO')) {
            return $this->findByRoleAndArea('admin', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'GERENTE DE') || str_contains($ocupacion, 'GERENTE OPERACIONES')) {
            return $this->findByRoleAndArea('admin', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'DIRECTOR DE CALIDAD')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (preg_match('/JEFE DE (RRHH|CONTABILIDAD|PRODUCCION|ALMACEN|MANTENIMIENTO|DESARROLLO GAL|SISTEMAS|TECNOLOGIAS|ANALISIS)/', $ocupacion)) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (preg_match('/JEFE PRODUCCION/', $ocupacion)) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'JEFE CONTROL CALIDAD') || str_contains($ocupacion, 'JEFE VALIDACIONES')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'RESPONSABLE FARMACEUTICO') || str_contains($ocupacion, 'RESPONSABLE DESARROLLO GALENICO') || str_contains($ocupacion, 'REG. FARMACEUTICO')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'JEFE DE VENTAS') || str_contains($ocupacion, 'JEFE MANTENIMIENTO') || str_contains($ocupacion, 'JEFE DE ALMACEN')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'TESORERA')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (preg_match('/ENCARGADO DE (LIMPIEZA|LOGISTICA|LICITACIONES|FACTURACION|DOCUMENTACION|HERRAMIENTAS|ANALISIS)/', $ocupacion)) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (preg_match('/ENC\.(VALIDACION|ESTUDIO|RECURSOS)/', $ocupacion)) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'SUPERVISORA EMPAQUE') || str_contains($ocupacion, 'SUPERVISOR PESADAS')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        if (str_contains($ocupacion, 'JEFE DESARROLLO GAL')) {
            return $this->findByRoleAndArea('supervisor', $areaId, $users, $user->id);
        }

        return null;
    }

    protected function findByRoleAndArea(string $role, int $areaId, Collection $users, int $excludeId): ?int
    {
        $candidates = $users->filter(fn ($u) => $u->hasRole($role) && $u->area_id === $areaId && $u->id !== $excludeId);

        if ($candidates->isNotEmpty()) {
            return $candidates->first()->id;
        }

        return null;
    }

    protected function parsePlantilla(): array
    {
        $lines = explode("\n", trim(self::PLANTILLA));
        $header = array_map(fn ($h) => strtolower(str_replace(' ', '_', trim($h))), str_getcsv(array_shift($lines)));
        $rows = [];

        foreach ($lines as $line) {
            if (trim($line) === '') {
                continue;
            }
            $fields = str_getcsv($line);
            if (count($fields) >= count($header)) {
                $rows[] = array_combine($header, $fields);
            }
        }

        return $rows;
    }

    protected function normalizeCarnet(string $carnet): string
    {
        return preg_replace('/\s+/', '', $carnet);
    }

    protected function generateEmail(string $carnet, string $codigo): string
    {
        $base = strtolower(preg_replace('/[^a-zA-Z0-9]/', '', $carnet));
        $email = $base.'@delta-sga.com';

        $existing = User::where('email', $email)->where('codigo_empleado', '!=', $codigo)->first();
        if ($existing) {
            $email = strtolower($codigo).'@delta-sga.com';
        }

        return $email;
    }

    protected function parseNombres(string $nombres): array
    {
        $parts = preg_split('/\s+/', trim($nombres));
        $parts = array_filter($parts);
        $count = count($parts);

        switch ($count) {
            case 1:
                return ['name' => $parts[0], 'nombre1' => $parts[0], 'nombre2' => null, 'apellido1' => null, 'apellido2' => null];
            case 2:
                return ['name' => implode(' ', $parts), 'nombre1' => $parts[0], 'nombre2' => null, 'apellido1' => $parts[1], 'apellido2' => null];
            case 3:
                return ['name' => implode(' ', $parts), 'nombre1' => $parts[0], 'nombre2' => null, 'apellido1' => $parts[1], 'apellido2' => $parts[2]];
            case 4:
                return ['name' => implode(' ', $parts), 'nombre1' => $parts[0], 'nombre2' => $parts[1], 'apellido1' => $parts[2], 'apellido2' => $parts[3]];
            default:
                return ['name' => implode(' ', $parts), 'nombre1' => $parts[0] ?? null, 'nombre2' => $parts[1] ?? null, 'apellido1' => $parts[2] ?? null, 'apellido2' => $parts[3] ?? null];
        }
    }

    protected function parseDate(string $dateStr): ?Carbon
    {
        try {
            return Carbon::createFromFormat('d/m/Y', $dateStr);
        } catch (\Exception $e) {
            return null;
        }
    }

    protected function getRoles(): array
    {
        return [
            'superadmin' => Role::findByName('superadmin', 'web'),
            'admin' => Role::findByName('admin', 'web'),
            'supervisor' => Role::findByName('supervisor', 'web'),
            'trabajador' => Role::findByName('trabajador', 'web'),
        ];
    }

    protected function getRoleByOccupation(string $ocupacion): array
    {
        $occ = strtoupper($ocupacion);

        if (str_contains($occ, 'GERENTE GENERAL')) {
            return ['admin', true];
        }
        if (preg_match('/GERENTE (ADMINISTRATIVO|COMERCIAL|DE MARKETING|OPERACIONES|REGIONAL)/', $occ)) {
            return ['admin', true];
        }
        if (str_contains($occ, 'DIRECTOR TECNICO') || str_contains($occ, 'DIRECTOR DE CALIDAD')) {
            return ['supervisor', true];
        }
        if (preg_match('/JEFE DE (RRHH|CONTABILIDAD|PRODUCCION|ALMACEN|MANTENIMIENTO|DESARROLLO GAL|SISTEMAS|TECNOLOGIAS|ANALISIS)/', $occ)) {
            return ['supervisor', true];
        }
        if (preg_match('/JEFE PRODUCCION/', $occ)) {
            return ['supervisor', true];
        }
        if (str_contains($occ, 'JEFE CONTROL CALIDAD') || str_contains($occ, 'JEFE VALIDACIONES')) {
            return ['supervisor', true];
        }
        if (str_contains($occ, 'RESPONSABLE FARMACEUTICO') || str_contains($occ, 'RESPONSABLE DESARROLLO GALENICO') || str_contains($occ, 'REG. FARMACEUTICO')) {
            return ['supervisor', true];
        }
        if (str_contains($occ, 'JEFE DE VENTAS') || str_contains($occ, 'JEFE MANTENIMIENTO') || str_contains($occ, 'JEFE DE ALMACEN')) {
            return ['supervisor', true];
        }
        if (str_contains($occ, 'TESORERA')) {
            return ['supervisor', true];
        }
        if (preg_match('/ENCARGADO DE (LIMPIEZA|LOGISTICA|LICITACIONES|FACTURACION|DOCUMENTACION|HERRAMIENTAS|ANALISIS)/', $occ)) {
            return ['trabajador', true];
        }
        if (preg_match('/ENC\.(VALIDACION|ESTUDIO|RECURSOS)/', $occ)) {
            return ['trabajador', true];
        }
        if (str_contains($occ, 'SUPERVISORA EMPAQUE') || str_contains($occ, 'SUPERVISOR PESADAS')) {
            return ['trabajador', true];
        }
        if (str_contains($occ, 'JEFE DESARROLLO GAL')) {
            return ['supervisor', true];
        }

        return ['trabajador', false];
    }
}
